import type { Alternative, CPE, Difficulty, ErrorType, Question } from '../types';
import { skillById } from './skills';

// Questões ORIGINAIS demonstrativas (não são cópias de provas). Ainda SEM revisão pedagógica humana.
type Alt = [text: string, analysis: string, error?: ErrorType];
interface Opt { cpe?: CPE; lessonId?: string; integrates?: string[]; twinLevel?: 1 | 2 | 3 }
const L = ['A', 'B', 'C', 'D', 'E'] as const;
/** A alternativa sem `error` é a correta. */
const N = (id: string, skillId: string, difficulty: Difficulty, topic: string, context: string, statement: string, alts: Alt[], explanation: string, fastMethod: string, card: [string, string], o: Opt = {}): Question => {
  const sk = skillById(skillId)!;
  const alternatives: Alternative[] = alts.map(([text, analysis, errorType], i) => ({ letter: L[i], text, analysis, errorType, correct: errorType ? undefined : true }));
  return { id, exam: 'ENEM', style: 'Estilo ENEM', subject: sk.subject, area: sk.area, topic, skillId, year: 2026, difficulty, type: 'objetiva', source: 'original_nexo', context, statement, alternatives, hints: [], explanation, fastMethod, flashcard: { front: card[0], back: card[1] }, lessonId: o.lessonId ?? sk.lessonId, cpe: o.cpe, integrates: o.integrates, twinLevel: o.twinLevel };
};
const cpe = (comando: string, prova: string, ...excesso: [string, string, string][]): CPE => ({ comando, prova, excesso: excesso.map(([letter, tipo, motivo]) => ({ letter, tipo, motivo })) });

